//! Map, Set, WeakMap, WeakSet.

pub const CASES: &[(&str, &str)] = &[
    // Map basics
    ("const m = new Map(); m.set('a', 1).set('b', 2); [m.get('a'), m.get('b'), m.get('c'), m.size, m.has('a'), m.has('z')].join()", "1,2,,2,true,false"),
    ("const m = new Map([[1, 'one'], [2, 'two']]); [...m.keys()].join() + '|' + [...m.values()].join() + '|' + [...m.entries()].join(';')", "1,2|one,two|1,one;2,two"),
    ("const m = new Map([['k', 1]]); m.set('k', 2); m.size + ':' + m.get('k')", "1:2"),
    ("const m = new Map([['a', 1], ['b', 2]]); [m.delete('a'), m.delete('a'), m.size, [...m.keys()].join()].join()", "true,false,1,b"),
    ("const m = new Map([['a', 1]]); m.clear(); m.size + ':' + m.has('a')", "0:false"),
    ("const o = {}, f = () => {}; const m = new Map([[o, 'obj'], [f, 'fn'], [NaN, 'nan'], [0, 'zero']]); [m.get(o), m.get(f), m.get(NaN), m.get(-0), m.get({})].join()", "obj,fn,nan,zero,"),
    ("const m = new Map(); m.set(-0, 'z'); Object.is([...m.keys()][0], 0)", "true"),
    ("const m = new Map(); m.set('1', 'str').set(1, 'num'); m.get('1') + ',' + m.get(1) + ',' + m.size", "str,num,2"),
    ("const m = new Map(); m.set('long string key ' + 1, 'v'); m.get('long string key 1')", "v"),
    ("[typeof Map, Map.length, Object.prototype.toString.call(new Map()), new Map() instanceof Map, Map.prototype[Symbol.iterator] === Map.prototype.entries].join()", "function,0,[object Map],true,true"),
    ("Map()", "TypeError!"),
    ("new Map([1, 2])", "TypeError!"),
    ("new Map(5)", "TypeError!"),
    ("Map.prototype.get.call(new Set(), 1)", "TypeError!"),
    ("const m = new Map([['x', 1], ['y', 2]]); const out = []; m.forEach(function (v, k, map) { out.push(k + v + (map === m) + this.tag); }, { tag: '!' }); out.join()", "x1true!,y2true!"),
    ("const m = new Map([['a', 1], ['b', 2]]); let s = ''; for (const [k, v] of m) s += k + v; s", "a1b2"),
    ("const m = new Map(Object.entries({ a: 1, b: 2 })); JSON.stringify(Object.fromEntries(m))", "{\"a\":1,\"b\":2}"),
    ("class Counter extends Map { inc(k) { this.set(k, (this.get(k) || 0) + 1); return this; } } const c = new Counter(); c.inc('a').inc('a').inc('b'); [c.get('a'), c.get('b'), c instanceof Map, c.size].join()", "2,1,true,2"),
    ("function* pairs() { yield ['g', 1]; yield ['h', 2]; } [...new Map(pairs())].join(';')", "g,1;h,2"),
    // insertion order
    ("const m = new Map(); m.set('b', 1); m.set('a', 2); m.set('c', 3); m.set('b', 9); [...m.keys()].join()", "b,a,c"),
    ("const m = new Map([['a', 1], ['b', 2], ['c', 3]]); m.delete('a'); m.set('a', 4); [...m].join(';')", "b,2;c,3;a,4"),
    ("const s = new Set([3, 1, 2, 3, 1]); [...s].join()", "3,1,2"),
    ("const m = new Map([[2, 'b'], [1, 'a'], ['1', 'c']]); [...m.keys()].map(k => typeof k + k).join()", "number2,number1,string1"),
    // mutation during iteration
    ("const m = new Map([['a', 1], ['b', 2]]); const seen = []; for (const [k] of m) { seen.push(k); if (k === 'a') m.set('c', 3); } seen.join()", "a,b,c"),
    ("const m = new Map([['a', 1], ['b', 2], ['c', 3]]); const seen = []; for (const [k] of m) { seen.push(k); if (k === 'a') m.delete('b'); } seen.join()", "a,c"),
    ("const m = new Map([['a', 1], ['b', 2]]); const seen = []; for (const [k] of m) { seen.push(k); m.delete(k); m.set(k + k, 0); if (seen.length > 5) break; } seen.join()", "a,b,aa,bb,aaaa,bbbb"),
    ("const s = new Set([1, 2, 3]); const seen = []; s.forEach(v => { seen.push(v); if (v === 1) { s.delete(2); s.add(4); } }); seen.join()", "1,3,4"),
    ("const s = new Set([1, 2, 3]); const seen = []; for (const v of s) { seen.push(v); if (v === 1) { s.clear(); s.add(9); } } seen.join()", "1,9"),
    ("const m = new Map([['a', 1]]); const it = m.keys(); it.next(); const end = it.next().done; m.set('late', 2); end + ',' + it.next().done", "true,true"),
    ("const m = new Map([[1, 1], [2, 2], [3, 3]]); const it = m.values(); it.next(); m.delete(1); m.delete(2); m.set(4, 4); [...it].join()", "3,4"),
    ("const s = new Set(); for (let i = 0; i < 2000; i++) s.add(i); for (let i = 0; i < 2000; i += 2) s.delete(i); let n = 0; for (const v of s) n += v; s.size + ':' + n", "1000:1000000"),
    // Set
    ("const s = new Set(); s.add(1).add('1').add(1); [s.size, s.has(1), s.has('1'), s.has(2), s.delete(1), s.has(1), s.size].join()", "2,true,true,false,true,false,1"),
    ("const s = new Set('hello'); [...s].join('') + s.size", "helo4"),
    ("const s = new Set([NaN, NaN, 0, -0]); s.size + ':' + s.has(NaN)", "2:true"),
    ("const s = new Set([1, 2]); [[...s.keys()].join(), [...s.values()].join(), [...s.entries()].join(';'), Set.prototype.keys === Set.prototype.values, Set.prototype[Symbol.iterator] === Set.prototype.values].join('|')", "1,2|1,2|1,1;2,2|true|true"),
    ("const a = new Set([1, 2, 3]), b = new Set([2, 3, 4]); [...a].filter(x => b.has(x)).join() + '|' + [...new Set([...a, ...b])].join()", "2,3|1,2,3,4"),
    ("[Object.prototype.toString.call(new Set()), Object.prototype.toString.call(new Set().values()), Object.prototype.toString.call(new Map().keys()), typeof new Set().values().next].join()", "[object Set],[object Set Iterator],[object Map Iterator],function"),
    ("const o = { id: 1 }; const s = new Set([o, o, { id: 1 }]); s.size", "2"),
    ("new Set(1)", "TypeError!"),
    ("Set.prototype.add.call(new Map(), 1)", "TypeError!"),
    ("const s = new Set([1, 2, 3]); const it = s[Symbol.iterator](); [it[Symbol.iterator]() === it, JSON.stringify(it.next()), [...it].join()].join('|')", "true|{\"value\":1,\"done\":false}|2,3"),
    // WeakMap / WeakSet
    ("const wm = new WeakMap(); const k = {}; wm.set(k, 'v'); [wm.get(k), wm.has(k), wm.has({}), wm.get({}), wm.delete(k), wm.has(k), wm.delete(k)].join()", "v,true,false,,true,false,false"),
    ("const k1 = {}, k2 = function () {}; const wm = new WeakMap([[k1, 1], [k2, 2]]); wm.get(k1) + wm.get(k2)", "3"),
    ("new WeakMap().set('str', 1)", "TypeError!"),
    ("new WeakMap().set(1, 1)", "TypeError!"),
    ("const wm = new WeakMap(); [wm.get(1), wm.has('x'), wm.delete(null)].join()", ",false,false"),
    ("const ws = new WeakSet(); const o = {}; [ws.add(o) === ws, ws.has(o), ws.has({}), ws.delete(o), ws.has(o)].join()", "true,true,false,true,false"),
    ("new WeakSet().add(5)", "TypeError!"),
    ("WeakMap()", "TypeError!"),
    ("[Object.prototype.toString.call(new WeakMap()), Object.prototype.toString.call(new WeakSet()), typeof WeakMap.prototype.keys, 'size' in new WeakMap()].join()", "[object WeakMap],[object WeakSet],undefined,false"),
    ("const priv = new WeakMap(); class P { constructor(n) { priv.set(this, { n }); } get n() { return priv.get(this).n; } } new P(7).n", "7"),
    ("WeakMap.prototype.get.call(new Map(), {})", "TypeError!"),
];
